/**
 * Embed the ANON-KIT files as JS string constants.
 *
 * These populate the persona and skills slots exactly as if the files had been
 * uploaded through the UI. Re-run after editing anything in anon-kit/:
 *   node scripts/gen-anon-kit.js
 */
import { readFileSync, writeFileSync } from "node:fs";

const FILES = {
  ANON_INSTRUCTION: "ANON.INSTRUCTION.md",
  ANON_GUIDE: "GUIDE.md",
  ANON_README: "README.md",
};

let out =
  "// GENERATED by scripts/gen-anon-kit.js - do not edit by hand.\n" +
  "// Source: anon-kit/ (the ANON-KIT files, verbatim).\n\n";

for (const [name, file] of Object.entries(FILES)) {
  const raw = readFileSync("anon-kit/" + file, "utf8");
  out += "export const " + name + " = " + JSON.stringify(raw) + ";\n";
}

writeFileSync("src/injected/anon-kit.generated.js", out);
console.log("wrote src/injected/anon-kit.generated.js");
